B.afS={"restricted-exhaust-airflow":0,"clogged-lint-pathway":1,"thermal-fuse-open":2,"accessible-thermal-reset":3,"motor-overheat-protector-open":4,"heating-element-failed":5,"electric-supply-connection-fault":6,"broken-drive-belt":7,"worn-drum-rollers":8,"idler-pulley-wear":9,"door-switch-failure":10,"motor-failure":11}
B.ZK=s([u._,u.c,u.a,"Unplug the dryer (or switch off its breaker) before moving it.","Restore power, run a short heat cycle, and re-check exterior airflow."],t.s)
